judicial.PartLawsuitGrid.register('judicial.assessmentnoticeoffice', 'judicial.parts.AssessmentNoticeOfficeWindow');


(function() {
    var rest = Ext._create('standard.ChoiceRestful');

    rest.doRequest(
        rest.getRoute('read', undefined, 'GET', {
            params: {
                filter: Ext.encode([
                    {property: "cache_path", value: "judicial.NOTICE_OFFICE_TYPE", stage: 100},
                    {property: 'active', value: true, stage: 101}
                ])
            },
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);

                function t(a) {
                    return (
                        (a.split(' ')).map(
                            function(w) {
                                var conjunctions = ['a', 'e', 'ao', 'ou', 'de', 'da', 'das'];

                                if(conjunctions.indexOf(w) < 0)
                                    return w.substr(0, 1).toUpperCase() + w.substr(1).toLowerCase();
                                else
                                    return w;
                            })
                        ).join(' ');
                }

                if(rst.success)
                    rst.collection.forEach(
                        function(choice) {
                            judicial.OutCourtLawsuitGrid.introductionRegister(
                                t(choice.label),
                                '',
                                'judicial.parts.AssessmentNoticeOfficeWindow',
                                {
                                    notice_office_type: choice.value
                                }
                            );
                        }
                    );
            }
        })
    );
})();
